			; Radar3D.cls 33: If hg < -14 Then hg = -14
			dw kw_scpltvl, var_radar3d_scanner_hg, -14
			dw kw_goto_iffalse, if307_1
			dw kw_ltov, -14, var_radar3d_scanner_hg
if307_1:

			; Radar3D.cls 34: If sx > x + 1 And sx < x + w - 3 And sy > y + 1 And sy < y + h - 3 And sy - hg > y + 1 And sy - hg < y + h - 3 Then
			dw kw_addl, var_radar3d_scanner_x, 1, tmp1
			dw kw_scpgtvv, var_radar3d_scanner_sx, tmp1
			dw kw_ftov, tmp0
			dw kw_add, var_radar3d_scanner_x, var_radar3d_scanner_w, tmp2
			dw kw_addl, tmp2, -3, tmp2
			dw kw_scpltvv, var_radar3d_scanner_sx, tmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_addl, var_radar3d_scanner_y, 1, tmp2
			dw kw_scpgtvv, var_radar3d_scanner_sy, tmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_add, var_radar3d_scanner_y, var_radar3d_scanner_h, tmp2
			dw kw_addl, tmp2, -3, tmp2
			dw kw_scpltvv, var_radar3d_scanner_sy, tmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_subvv, var_radar3d_scanner_sy, var_radar3d_scanner_hg, tmp1
			dw kw_addl, var_radar3d_scanner_y, 1, tmp2
			dw kw_scpgtvv, tmp1, tmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_subvv, var_radar3d_scanner_sy, var_radar3d_scanner_hg, tmp1
			dw kw_add, var_radar3d_scanner_y, var_radar3d_scanner_h, tmp2
			dw kw_addl, tmp2, -3, tmp2
			dw kw_scpltvv, tmp1, tmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if308_1

			; Radar3D.cls 35: If hg > 0 Then tp = sy - hg Else tp = sy
			dw kw_scpgtvl, var_radar3d_scanner_hg, 0
			dw kw_goto_iffalse, if309_1
			dw kw_subvv, var_radar3d_scanner_sy, var_radar3d_scanner_hg, var_radar3d_scanner_tp
			dw if309_e_go
