			dw kw_vtov, var_radar3d_scanner_sy, var_radar3d_scanner_tp
if309_e:

			; Radar3D.cls 36: ln = Abs(hg)
			dw kw_absv, var_radar3d_scanner_hg, var_radar3d_scanner_ln

			; Radar3D.cls 37: If ln > 0 Then E3.Box sx, tp, 1, ln, frame + 3
			dw kw_scpgtvl, var_radar3d_scanner_ln, 0
			dw kw_goto_iffalse, if310_1
			dw kw_addl, var_radar3d_scanner_frame, 3, tmp4
			dw fn_e3_box, var_radar3d_scanner_sx, var_radar3d_scanner_tp, lit_1, var_radar3d_scanner_ln, tmp4
if310_1:

			; Radar3D.cls 38: E3.Dot sx - 1, sy - hg - 1, c
			dw kw_addl, var_radar3d_scanner_sx, -1, tmp0
			dw kw_subvv, var_radar3d_scanner_sy, var_radar3d_scanner_hg, tmp1
			dw kw_dec, tmp1
			dw fn_e3_dot, tmp0, tmp1, var_radar3d_scanner_c

			; Radar3D.cls 39: End If
